//! The nspasteboard.org markers on our transcript write, and the check of
//! what a clipboard manager would see while the transcript is on the
//! clipboard (RS-05: no manager is installed on the test Mac, so the spike
//! reads the types back instead of running Maccy, Raycast or Paste).
//!
//! hex writes `TransientType` and `AutoGeneratedType`; Handy's concealed
//! paste (`paste_tx/macos.rs` `CONCEALMENT_TYPES`) adds `ConcealedType`.
//! R5 W-07 asks for all three.

use serde::Serialize;

pub const TEXT: &str = "public.utf8-plain-text";
pub const TRANSIENT: &str = "org.nspasteboard.TransientType";
pub const AUTO_GENERATED: &str = "org.nspasteboard.AutoGeneratedType";
pub const CONCEALED: &str = "org.nspasteboard.ConcealedType";
pub const ALL: [&str; 3] = [TRANSIENT, AUTO_GENERATED, CONCEALED];

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
pub struct ManagerView {
    /// Items on the clipboard while the transcript is there.
    pub items: usize,
    /// The item carrying text has all three markers.
    pub text_item_marked: bool,
    pub missing_markers: Vec<String>,
    /// Anything besides the one marked text item (should be nothing: the
    /// user's own items must not stay visible next to the transcript).
    pub other_types: Vec<String>,
}

impl ManagerView {
    /// A manager following nspasteboard.org skips an item that carries
    /// `TransientType` or `ConcealedType`. True when every item with text is
    /// marked that way and nothing else is on the clipboard.
    pub fn convention_says_skip(&self) -> bool {
        self.items == 1 && self.text_item_marked && self.other_types.is_empty()
    }
}

/// `types`: the type names per item, as read without asking for data (a
/// type listing does not trigger our lazy text).
pub fn manager_view(types: &[Vec<String>]) -> ManagerView {
    let text_item = types.iter().find(|t| t.iter().any(|u| u == TEXT));
    let missing: Vec<String> = match text_item {
        Some(t) => ALL
            .iter()
            .filter(|m| !t.iter().any(|u| u == *m))
            .map(|m| m.to_string())
            .collect(),
        None => ALL.iter().map(|m| m.to_string()).collect(),
    };
    let other_types = types
        .iter()
        .flatten()
        .filter(|u| *u != TEXT && !ALL.contains(&u.as_str()))
        .cloned()
        .collect();
    ManagerView {
        items: types.len(),
        text_item_marked: text_item.is_some() && missing.is_empty(),
        missing_markers: missing,
        other_types,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn t(v: &[&str]) -> Vec<String> {
        v.iter().map(|s| s.to_string()).collect()
    }

    #[test]
    fn marked_transcript_is_skipped() {
        let v = manager_view(&[t(&[TRANSIENT, AUTO_GENERATED, CONCEALED, TEXT])]);
        assert!(v.text_item_marked);
        assert!(v.convention_says_skip());
    }

    #[test]
    fn missing_marker_or_leftover_items_fail() {
        let v = manager_view(&[t(&[TRANSIENT, TEXT])]);
        assert_eq!(v.missing_markers, t(&[AUTO_GENERATED, CONCEALED]));
        assert!(!v.convention_says_skip());
        let v = manager_view(&[
            t(&[TRANSIENT, AUTO_GENERATED, CONCEALED, TEXT]),
            t(&["public.png"]),
        ]);
        assert_eq!(v.other_types, t(&["public.png"]));
        assert!(!v.convention_says_skip());
        let v = manager_view(&[]);
        assert!(!v.text_item_marked);
    }
}
